          <el-form :model="courseForm" inline class="filters"><el-form-item label="课程名称"><el-input v-model="courseForm.name" placeholder="课程名称" /></el-form-item><el-form-item label="价格"><el-input-number v-model="courseForm.price" :min="0" :precision="2" /></el-form-item><el-form-item label="课程说明"><el-input v-model="courseForm.description" placeholder="简要描述" /></el-form-item><el-button type="primary" @click="addCourse">创建课程</el-button></el-form>
          <el-table :data="rows" v-loading="loading" stripe><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="110" /><el-table-column label="操作" width="185"><template #default="{row}"><div class="table-actions"><el-button link type="primary" @click="editCourse(row)">修改</el-button><el-button link type="primary" @click="courseStatus(row)">{{ row.status==='PUBLISHED'?'下架':'上架' }}</el-button></div></template></el-table-column></el-table>
