        <el-card v-if="role==='ADMIN'&&activeView==='classrooms'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>教室资源</h3><p>排课时会校验教室容量和可用状态</p></div></div></template><el-form :model="roomForm" inline class="filters"><el-form-item label="教室名称"><el-input v-model="roomForm.name" /></el-form-item><el-form-item label="容量"><el-input-number v-model="roomForm.capacity" :min="1" /></el-form-item><el-button type="primary" @click="addRoom">添加教室</el-button></el-form><el-table :data="rows" v-loading="loading"><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" /><el-table-column label="操作" min-width="170"><template #default="{row}"><el-button link type="primary" @click="openRoomEdit(row)">修改</el-button><el-button link type="primary" @click="toggleRoom(row)">{{ row.status==='ACTIVE'?'停用':'启用' }}</el-button></template></el-table-column></el-table></el-card>

        <el-card v-if="role==='ADMIN'&&activeView==='schedules'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>排课安排</h3><p>冲突由后端以事务锁和半开时间区间校验</p></div></div></template><el-form :model="scheduleForm" inline class="filters"><el-form-item label="班级"><el-select v-model="scheduleForm.classId" @change="selectedClassId=$event"><el-option v-for="c in classes" :key="c.id" :label="`${c.name} (#${c.id})`" :value="c.id" /></el-select></el-form-item><el-form-item label="教室"><el-select v-model="scheduleForm.classroomId"><el-option v-for="room in rooms.filter(x=>x.status==='ACTIVE')" :key="room.id" :label="`${room.name} (${room.capacity})`" :value="room.id" /></el-select></el-form-item><el-form-item label="开始"><el-date-picker v-model="scheduleForm.startTime" type="datetime" value-format="YYYY-MM-DDTHH:mm" /></el-form-item><el-form-item label="结束"><el-date-picker v-model="scheduleForm.endTime" type="datetime" value-format="YYYY-MM-DDTHH:mm" /></el-form-item><el-button type="primary" @click="addSchedule">{{ scheduleEditId?'保存修改':'创建课次' }}</el-button><el-button v-if="scheduleEditId" @click="scheduleEditId=undefined">取消修改</el-button><el-button @click="loadView">刷新课表</el-button></el-form><el-table :data="rows" v-loading="loading"><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="130" /><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='SCHEDULED'" link type="primary" @click="editSchedule(row)">修改课次</el-button></template></el-table-column></el-table></el-card>

