        <el-card v-if="role==='TEACHER'&&activeView==='attendance'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>批量考勤</h3><p>重复登记会更新原记录，不会产生重复行</p></div></div></template><div class="inline-form"><el-form-item label="课次"><el-select v-model="selectedScheduleId" placeholder="选择课次"><el-option v-for="s in schedules" :key="s.id" :label="`课次 #${s.id} · 班级 ${s.classId} · ${formatTime(s.startTime)}`" :value="s.id" /></el-select></el-form-item><el-button @click="loadAttendance">读取学生名单</el-button><el-button type="primary" @click="saveAttendance">保存考勤</el-button></div><el-table class="section-gap" :data="attendanceRoster" v-loading="loading"><el-table-column prop="studentId" label="学生 ID"/><el-table-column prop="realName" label="学生姓名"/><el-table-column label="考勤状态"><template #default="{row}"><el-select v-model="row.editStatus" placeholder="选择状态"><el-option v-for="v in ['PRESENT','LATE','ABSENT','LEAVE']" :key="v" :label="v" :value="v" /></el-select></template></el-table-column><el-table-column prop="status" label="已保存状态"/></el-table></el-card>

