        <el-card v-if="role==='TEACHER'&&activeView==='exams'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>考试与组卷</h3><p>组卷规则按题型与难度抽取，并保存不可变快照</p></div></div></template><el-form :model="examForm" inline class="filters"><el-form-item label="班级"><el-select v-model="examForm.classId"><el-option v-for="c in classes" :key="c.id" :label="`${c.name} (#${c.id})`" :value="c.id"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="examForm.title"/></el-form-item><el-form-item label="开始"><el-date-picker v-model="examForm.startTime" type="datetime" value-format="YYYY-MM-DDTHH:mm"/></el-form-item><el-form-item label="结束"><el-date-picker v-model="examForm.endTime" type="datetime" value-format="YYYY-MM-DDTHH:mm"/></el-form-item><el-form-item label="分钟"><el-input-number v-model="examForm.durationMinutes" :min="1" :max="1440"/></el-form-item><el-button type="primary" @click="addExam">创建考试</el-button></el-form><el-form :model="ruleForm" inline class="filters"><el-form-item label="组卷题型"><el-select v-model="ruleForm.type"><el-option v-for="v in ['SINGLE_CHOICE','MULTIPLE_CHOICE','TRUE_FALSE','SHORT_ANSWER']" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="难度"><el-select v-model="ruleForm.difficulty"><el-option v-for="v in ['EASY','MEDIUM','HARD']" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="数量"><el-input-number v-model="ruleForm.count" :min="1"/></el-form-item><el-form-item label="单题分数"><el-input-number v-model="ruleForm.score" :min="0.01" :precision="2"/></el-form-item><el-form-item label="考试 ID"><el-input-number v-model="selectedExamId" :min="1"/></el-form-item><el-button @click="generateExam()">按规则组卷</el-button><el-button @click="loadView">刷新</el-button></el-form><el-table :data="rows" v-loading="loading"><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="130"/><el-table-column label="操作" width="230"><template #default="{row}"><el-button v-if="row.status==='DRAFT'" link type="primary" @click="generateExam(row)">组卷</el-button><el-button v-if="row.status==='DRAFT'" link type="primary" @click="examAction(row,'publish')">发布</el-button><el-button v-if="row.status==='PUBLISHED'" link type="warning" @click="examAction(row,'close')">关闭</el-button><el-button link type="primary" @click="examAction(row,'results')">成绩</el-button></template></el-table-column></el-table></el-card>

        <el-card v-if="role==='TEACHER'&&activeView==='results'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>班级考试成绩</h3><p>主观题需要完成批改后才公布最终成绩</p></div><div class="inline-form"><el-input-number v-model="selectedExamId" :min="1" placeholder="考试 ID"/><el-button @click="loadResults">查询成绩</el-button><el-button @click="loadPendingAnswers">待批简答题</el-button></div></div></template><el-table :data="rows" v-loading="loading"><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="130"/><el-table-column label="答题批改"><template #default="{row}"><el-tag v-if="row.status!=='GRADED'" type="warning">待完成主观题批改</el-tag><span v-else>已出分</span></template></el-table-column></el-table><div v-if="pendingExamAnswers.length" class="section-gap"><h3>待批简答题</h3><el-table :data="pendingExamAnswers"><el-table-column prop="studentName" label="学生"/><el-table-column prop="content" label="题目" min-width="200"/><el-table-column prop="answerJson" label="学生答案" min-width="200"/><el-table-column prop="maxScore" label="满分"/><el-table-column label="操作"><template #default="{row}"><el-button type="primary" link @click="gradeExamAnswer(row)">批改</el-button></template></el-table-column></el-table></div></el-card>

        <el-card v-if="role==='STUDENT'&&['overview','courses'].includes(activeView)" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>课程目录</h3><p>进入课程后查看当前开放报名的班级</p></div></div></template><el-table :data="rows" v-loading="loading"><el-table-column prop="name" label="课程" min-width="150"/><el-table-column prop="description" label="课程说明" min-width="230" show-overflow-tooltip/><el-table-column prop="price" label="价格" width="100"/><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="selectedCourse=row;loadClassesForCourse()">查看开放班级</el-button></template></el-table-column></el-table><div v-if="selectedCourse" class="section-gap"><div class="card-title"><h3>{{ selectedCourse.name }} · 开放班级</h3><el-button text @click="selectedCourse=null;openClasses=[]">收起</el-button></div><el-table :data="openClasses"><el-table-column prop="id" label="班级 ID"/><el-table-column prop="name" label="班级"/><el-table-column prop="teacherId" label="教师"/><el-table-column prop="capacity" label="容量"/><el-table-column prop="enrolledCount" label="已报名"/><el-table-column prop="startDate" label="开课日期"/><el-table-column label="报名"><template #default="{row}"><el-button type="primary" size="small" @click="enroll(row.id)">报名并创建订单</el-button></template></el-table-column></el-table></div></el-card>

        <el-card v-if="role==='STUDENT'&&activeView==='myClasses'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>我的班级</h3><p>模拟支付成功后正式加入班级</p></div></div></template><el-table :data="rows" v-loading="loading"><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="130"/><el-table-column label="课表"><template #default="{row}"><el-button link type="primary" @click="showClassSchedule(row)">查看课表</el-button></template></el-table-column></el-table></el-card>

        <el-card v-if="role==='STUDENT'&&activeView==='orders'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>我的订单</h3><p>支付成功后自动正式入班；重复支付不会重复记账</p></div></div></template><el-table :data="rows" v-loading="loading"><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="130"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='PENDING'" link type="primary" @click="pay(row)">模拟支付</el-button><el-button v-if="row.status==='PENDING'" link type="danger" @click="cancelOrder(row)">取消</el-button></template></el-table-column></el-table></el-card>

        <el-card v-if="role==='STUDENT'&&activeView==='schedules'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>我的课表</h3><p>仅聚合本人正式加入班级的课次</p></div></div></template><el-table :data="rows" v-loading="loading"><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="130"/></el-table></el-card>
        <el-card v-if="role==='STUDENT'&&activeView==='attendance'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>我的考勤</h3><p>考勤记录为只读数据</p></div></div></template><el-table :data="rows" v-loading="loading"><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="130"/></el-table></el-card>
        <el-card v-if="role==='STUDENT'&&activeView==='assignments'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>我的作业</h3><p>提交后截止前可修改，教师批改后锁定</p></div></div></template><el-table :data="rows" v-loading="loading"><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="130"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='PUBLISHED'&&row.submissionStatus!=='GRADED'" link type="primary" @click="submitAssignment(row)">{{ row.submissionId?'修改提交':'提交作业' }}</el-button></template></el-table-column></el-table></el-card>
        <el-card v-if="role==='STUDENT'&&activeView==='exams'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>在线考试</h3><p>服务器检查开考时间、考试截止时间和答卷状态</p></div></div></template><el-table :data="rows" v-loading="loading"><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="130"/><el-table-column label="操作" width="170"><template #default="{row}"><el-button v-if="row.status==='PUBLISHED'" link type="primary" @click="startExam(row)">开始 / 继续</el-button><el-button link type="success" @click="showResult(row)">查看成绩</el-button></template></el-table-column></el-table><div v-if="examStart" class="exam-panel section-gap"><div class="card-title"><div><h3>答题中 · {{ examStart.questions.length }} 道题</h3><p>截止时间：{{ formatTime(examStart.deadline) }}</p></div><el-button type="primary" @click="submitExam">提交整份答卷</el-button></div><div v-for="(q,index) in examStart.questions" :key="q.id" class="exam-question"><div class="exam-question-title">{{ Number(index)+1 }}. {{ q.content }} <span class="muted-copy">（{{ q.score }} 分）</span></div><el-radio-group v-if="q.type==='SINGLE_CHOICE'||q.type==='TRUE_FALSE'" v-model="answers[q.id]" class="choice-list"><el-radio v-for="option in (typeof q.optionsJson==='string'?JSON.parse(q.optionsJson||'[]'):q.optionsJson||[])" :key="option.id||option" :value="option.id||option">{{ option.text||option }}</el-radio><el-radio v-if="q.type==='TRUE_FALSE'" :value="true">正确</el-radio><el-radio v-if="q.type==='TRUE_FALSE'" :value="false">错误</el-radio></el-radio-group><el-checkbox-group v-else-if="q.type==='MULTIPLE_CHOICE'" v-model="answers[q.id]"><el-checkbox v-for="option in (typeof q.optionsJson==='string'?JSON.parse(q.optionsJson||'[]'):q.optionsJson||[])" :key="option.id||option" :value="option.id||option">{{ option.text||option }}</el-checkbox></el-checkbox-group><el-input v-else v-model="answers[q.id]" type="textarea" :rows="4" placeholder="写下你的答案"/></div></div></el-card>
        <el-card v-if="role==='STUDENT'&&activeView==='notifications'" class="content-card section-gap" shadow="never"><template #header><div class="card-title"><div><h3>站内通知</h3><p>未读 {{ notificationUnread }} 条</p></div></div></template><el-table :data="rows" v-loading="loading"><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" min-width="150"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="!row.readAt" link type="primary" @click="markRead(row)">标为已读</el-button><el-tag v-else type="info">已读</el-tag></template></el-table-column></el-table></el-card>

        <el-card v-if="!((role==='ADMIN'&&['users','courses','classes','classrooms','schedules','orders'].includes(activeView))||(role==='TEACHER'&&['overview','classes','students','schedules','attendance','assignments','submissions','questions','exams','results'].includes(activeView))||(role==='STUDENT'&&['overview','courses','myClasses','orders','schedules','attendance','assignments','exams','notifications'].includes(activeView)))" class="content-card section-gap" shadow="never"><div class="empty-state">选择左侧功能开始使用</div></el-card>
        <el-dialog v-model="classEditVisible" title="修改班级" width="560px"><el-form :model="classEditForm" label-position="top" class="form-grid"><el-form-item label="课程"><el-select v-model="classEditForm.courseId"><el-option v-for="c in courses" :key="c.id" :label="`${c.name} (#${c.id})`" :value="c.id"/></el-select></el-form-item><el-form-item label="主讲教师"><el-select v-model="classEditForm.teacherId"><el-option v-for="t in teachers" :key="t.id" :label="`${t.realName} (#${t.id})`" :value="t.id"/></el-select></el-form-item><el-form-item label="班级名称"><el-input v-model="classEditForm.name"/></el-form-item><el-form-item label="容量"><el-input-number v-model="classEditForm.capacity" :min="1"/></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="classEditForm.startDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="classEditForm.endDate" type="date" value-format="YYYY-MM-DD"/></el-form-item></el-form><template #footer><el-button @click="classEditVisible=false">取消</el-button><el-button type="primary" @click="saveClassEdit">保存修改</el-button></template></el-dialog>
        <el-dialog v-model="roomEditVisible" title="修改教室" width="440px"><el-form :model="roomEditForm" label-position="top"><el-form-item label="教室名称"><el-input v-model="roomEditForm.name"/></el-form-item><el-form-item label="容量"><el-input-number v-model="roomEditForm.capacity" :min="1"/></el-form-item></el-form><template #footer><el-button @click="roomEditVisible=false">取消</el-button><el-button type="primary" @click="saveRoomEdit">保存修改</el-button></template></el-dialog>
        <el-dialog v-model="assignmentEditVisible" title="修改作业草稿" width="560px"><el-form :model="assignmentEditForm" label-position="top"><el-form-item label="标题"><el-input v-model="assignmentEditForm.title"/></el-form-item><el-form-item label="截止时间"><el-date-picker v-model="assignmentEditForm.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm"/></el-form-item><el-form-item label="内容"><el-input v-model="assignmentEditForm.content" type="textarea" :rows="5"/></el-form-item></el-form><template #footer><el-button @click="assignmentEditVisible=false">取消</el-button><el-button type="primary" @click="saveAssignmentEdit">保存草稿</el-button></template></el-dialog>
        <el-dialog v-model="questionEditVisible" title="修改题目" width="620px"><el-form :model="questionEditForm" label-position="top" class="form-grid"><el-form-item label="课程"><el-select v-model="questionEditForm.courseId"><el-option v-for="id in [...new Set(classes.map(c=>c.courseId))]" :key="id" :label="`课程 #${id}`" :value="id"/></el-select></el-form-item><el-form-item label="题型"><el-select v-model="questionEditForm.type"><el-option v-for="v in ['SINGLE_CHOICE','MULTIPLE_CHOICE','TRUE_FALSE','SHORT_ANSWER']" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="难度"><el-select v-model="questionEditForm.difficulty"><el-option v-for="v in ['EASY','MEDIUM','HARD']" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="题目"><el-input v-model="questionEditForm.content"/></el-form-item><el-form-item label="选项 JSON"><el-input v-model="questionEditForm.optionsJson" type="textarea" :rows="3"/></el-form-item><el-form-item label="答案 JSON"><el-input v-model="questionEditForm.answerJson"/></el-form-item></el-form><template #footer><el-button @click="questionEditVisible=false">取消</el-button><el-button type="primary" @click="saveQuestionEdit">保存修改</el-button></template></el-dialog>
      </section>
    </main>
  </div>
</template>
